/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_priceDiscAdmAdjustment">PriceDiscAdmAdjustment</param>
/// <param name = "_priceDiscAdmTrans">PriceDiscAdmTrans</param>
/// <param name = "_eventHandlerResult">EventHandlerResult</param>
[SubscribesTo(classStr(PriceDiscAdmAdjustment), delegateStr(PriceDiscAdmAdjustment,retrievePurchSalesPriceAmountDelegate ))]
public static void PriceAmountDelegate(PriceDiscAdmAdjustment _priceDiscAdmAdjustment, PriceDiscAdmTrans _priceDiscAdmTrans, EventHandlerResult _eventHandlerResult)
{
    Amount              ret, price;
    InventTable         inventTable;
    PriceBase           priceBase   = _priceDiscAdmAdjustment.parmPriceBase();
    percent             pricechg    = _priceDiscAdmAdjustment.parmPriceChange();
    Amount              priceAmount = _priceDiscAdmAdjustment.parmPriceAmount();

    switch (priceBase)
    {
        case PriceBase::AVAOldPrice:
            ret   = _priceDiscAdmTrans.KCS_AmountOld * (1 + (priceChg / 100)) + priceAmount;
            break;
        case priceBase::AVAHK1:
            if (_priceDiscAdmTrans.ItemCode == PriceDiscProductCodeType::Table)
            {
                inventTable             = InventTable::find(_priceDiscAdmTrans.ItemRelation);
                if (inventTable.inventTableModuleSales().NDX_showHK1current())
                {
                    price                   = inventTable.inventTableModuleSales().NDX_showHK1current() / 1000 * inventTable.salesPriceUnit();
                }
                ret                     = price * (1 + (priceChg / 100)) + priceAmount;
            }
            break;
        case priceBase::AVAHK2:
            if (_priceDiscAdmTrans.ItemCode == PriceDiscProductCodeType::Table)
            {
                inventTable             = InventTable::find(_priceDiscAdmTrans.ItemRelation);
                price                   = inventTable.NDX_HK2();
                ret                     = price * (1 + (priceChg / 100)) + priceAmount;
            }
            break;                
    }
    _eventHandlerResult.result(ret);
}
